import React, { Component } from 'react';

const FormattedDateProvider = React.lazy(() => import('../tools/FormattedDateProvider'));
const QRCodeReader = React.lazy(() => import('../QRCodeReader/QRCodeReader'));
const QRCodeGenerator = React.lazy(() => import('../QRCodeGenerator/QRCodeGenerator'));

const TABS = [
    { key: 'date', label: 'Date Formatter' },
    { key: 'qr-reader', label: 'QR Reader' },
    { key: 'qr-generator', label: 'QR Generator' },
];

class Public extends Component {

    constructor(props) {
        super(props);
        this.state = {
            activeTab: 'date',
        };
    }

    componentDidMount() {
        document.title = "Satanlabs - Public Tools";
    }

    renderActiveTab() {
        switch (this.state.activeTab) {
            case 'date':
                return <FormattedDateProvider />;
            case 'qr-reader':
                return <QRCodeReader />;
            case 'qr-generator':
                return <QRCodeGenerator />;
            default:
                return null;
        }
    }

    render() {
        const { activeTab } = this.state;

        return (
            <div style={styles.container}>
                <div style={styles.header}>
                    <h2 style={styles.title}>Satanlabs — Public Tools</h2>
                    <div style={styles.tabBar}>
                        {TABS.map(tab => (
                            <button
                                key={tab.key}
                                style={{
                                    ...styles.tab,
                                    ...(activeTab === tab.key ? styles.activeTab : {}),
                                }}
                                onClick={() => this.setState({ activeTab: tab.key })}
                            >
                                {tab.label}
                            </button>
                        ))}
                    </div>
                </div>
                <div style={styles.content}>
                    <React.Suspense fallback={<div style={styles.loading}>Loading...</div>}>
                        {this.renderActiveTab()}
                    </React.Suspense>
                </div>
            </div>
        );
    }
}

const styles = {
    container: {
        minHeight: '100vh',
        backgroundColor: '#f5f5f5',
        padding: '20px',
    },
    header: {
        textAlign: 'center',
        marginBottom: '24px',
    },
    title: {
        fontSize: '24px',
        fontWeight: 'bold',
        color: '#333',
        marginBottom: '16px',
    },
    tabBar: {
        display: 'flex',
        justifyContent: 'center',
        gap: '8px',
        flexWrap: 'wrap',
    },
    tab: {
        padding: '10px 20px',
        border: '1px solid #ddd',
        borderRadius: '6px',
        backgroundColor: '#fff',
        cursor: 'pointer',
        fontSize: '14px',
        fontWeight: '500',
        color: '#555',
        transition: 'all 0.2s',
    },
    activeTab: {
        backgroundColor: '#4a90d9',
        color: '#fff',
        borderColor: '#4a90d9',
    },
    content: {
        maxWidth: '1200px',
        margin: '0 auto',
    },
    loading: {
        textAlign: 'center',
        padding: '40px',
        color: '#888',
    },
};

export default Public;
